using EEMS.SharedKernel.Domain;
namespace EEMS.Modules.Teams.Domain;
public sealed class TaskPriority:Entity<short>{private TaskPriority(){}private TaskPriority(short id,string code,string name,short rank){if(id<=0||rank<=0)throw new ArgumentOutOfRangeException(nameof(id));Id=id;Code=Text(code,40).ToUpperInvariant();Name=Text(name,100);Rank=rank;IsActive=true;}public string Code{get;private set;}=string.Empty;public string Name{get;private set;}=string.Empty;public short Rank{get;private set;}public bool IsActive{get;private set;}public static TaskPriority Create(short id,string code,string name,short rank)=>new(id,code,name,rank);private static string Text(string v,int m){var t=v?.Trim()??string.Empty;return t.Length is >0&&t.Length<=m?t:throw new ArgumentException("Value is invalid.");}}
